/// <summary>
/// PaffH 18.03.22
/// set grid columns scalable with col splitter
/// </summary>
public void init()
{
    next init();
    MapIterator mapIterator = new MapIterator(gridControls);
    while (mapIterator.more())
    {
        FormGridControl gridControl = mapIterator.value();
        gridControl.autoSizeColumns(true);
        gridControl.widthMode(FormWidth::SizeToAvailable);
        FormControl formControl = gridControl.controlNum(1);
        formControl.widthMode(FormWidth::SizeToAvailable);
        mapIterator.next();
    }
}
